text:
{
  "outline": [
    {
      "title": "极限与连续基础",
      "summary": "介绍数列和函数极限的精确定义、性质及两个重要极限，为微积分打下地基。",
      "kc_names": ["数列极限", "函数极限", "极限与连续"]
    },
    {
      "title": "无穷小量与连续性",
      "summary": "学习无穷小量的比较、等价无穷小替换以及函数连续性的判定与间断点分类。",
      "kc_names": ["无穷小量", "高等价无穷小", "函数的连续性"]
    },
    {
      "title": "导数与求导法则",
      "summary": "掌握导数的定义、几何意义、基本初等函数导数表以及四则、复合、反函数求导法则。",
      "kc_names": ["导数", "基本初等函数导数表", "求导法则"]
    },
    {
      "title": "高阶导数与隐函数求导",
      "summary": "学习高阶导数的计算以及隐函数、幂指函数的求导方法。",
      "kc_names": ["高阶导数", "隐函数求导", "对数求导法", "幂指函数求导"]
    },
    {
      "title": "微分中值定理与洛必达法则",
      "summary": "理解罗尔、拉格朗日、柯西中值定理，并应用洛必达法则求极限。",
      "kc_names": ["罗尔定理", "拉格朗日中值定理", "柯西中值定理", "洛必达法则"]
    },
    {
      "title": "泰勒公式与积分入门",
      "summary": "学习泰勒公式展开、余项及近似计算，并掌握不定积分与定积分的基本方法。",
      "kc_names": ["泰勒公式", "不定积分", "定积分", "牛顿-莱布尼茨公式"]
    }
  ],
  "glossary": [
    {"term": "数列极限", "definition": "当 $n$ 无限增大时，数列 $a_n$ 无限趋近于常数 $A$，则称 $A$ 为数列的极限。"},
    {"term": "无穷小量", "definition": "极限为 $0$ 的变量，是微积分中分析函数局部行为的重要工具。"},
    {"term": "导数", "definition": "函数在某点的瞬时变化率，几何上表示曲线在该点切线的斜率。"},
    {"term": "等价无穷小", "definition": "两个无穷小量之比极限为 $1$，在乘除运算中可互相替换简化计算。"},
    {"term": "洛必达法则", "definition": "当极限为 $0/0$ 或 $\\infty/\\infty$ 时，分子分母分别求导再求极限的方法。"},
    {"term": "泰勒公式", "definition": "用多项式逼近函数，并给出误差估计，是近似计算和求极限的有力工具。"},
    {"term": "不定积分", "definition": "导数的逆运算，求原函数族，记为 $\\int f(x) dx$。"},
    {"term": "定积分", "definition": "黎曼和的极限，表示曲边梯形的面积，由牛顿-莱布尼茨公式计算。"}
  ],
  "suggested_questions": [
    "如何用 $\\varepsilon-N$ 语言证明数列 $1/n$ 的极限是 $0$？",
    "等价无穷小替换在加减法中为什么不能直接使用？",
    "函数 $f(x)=|x|$ 在 $x=0$ 处为什么不可导？",
    "拉格朗日中值定理的几何意义是什么？",
    "如何用洛必达法则求 $\\lim_{x\\to 0} \\frac{\\sin x}{x}$？",
    "泰勒公式中拉格朗日余项和佩亚诺余项有什么区别？"
  ]
}
